import unittest
from candidate import remove_duplicates
from unittest.mock import Mock

class TestRemoveDuplicates(unittest.TestCase):
    def test_normal_case(self):
        self.assertEqual(remove_duplicates([1, 2, 3, 2, 4]), [1, 3, 4])

    def test_empty_list(self):
        self.assertEqual(remove_duplicates([]), [])

    def test_single_element_list(self):
        self.assertEqual(remove_duplicates([1]), [1])

    def test_all_duplicates(self):
        self.assertEqual(remove_duplicates([2, 2, 2, 2]), [])

    def test_boundary_case(self):
        self.assertEqual(remove_duplicates([1, 1]), [1])

    def test_negative_numbers(self):
        self.assertEqual(remove_duplicates([-1, -2, -2, 1]), [-1, 1])

    def test_mixed_numbers(self):
        self.assertEqual(remove_duplicates([-1, 1, -2, 2]), [-1, 1, 2])

    def test_none_value(self):
        self.assertIsNone(remove_duplicates(None))

    def test_list_with_float(self):
        self.assertEqual(remove_duplicates([1.5, 2.5, 3.5, 2.5]), [1.5, 3.5])

    def test_type_errors(self):
        with self.assertRaises(TypeError):
            remove_duplicates(1)
        with self.assertRaises(TypeError):
            remove_duplicates('string')

if __name__ == '__main__':
    unittest.main()
